    void* design_handle = iki_create_design("xsim.dir/pfm_top_wrapper_behav/xsim.mem", (void *)relocate, (void *)sensitize, (void *)simulate, (void*)0, 8, isimBridge_getWdbWriter(), 0, argc, argv);
